select case when year(ss.sale_date) < 2024 then 'before_2024' when year(ss.sale_date) = 2024 then '2024' else 'after_2024' end as sale_cohort, sum(i.quantity) as total_quantity, avg(i.quantity) as avg_quantity from inventory i left outer join store_sales ss on i.store_id = ss.store_id and i.product_id = ss.product_id where i.quantity >= 85 group by case when year(ss.sale_date) < 2024 then 'before_2024' when year(ss.sale_date) = 2024 then '2024' else 'after_2024' end;
